static void
mpz_powm(mrb_state *mrb, mpz_t *zz, mpz_t *x, mrb_int ex, mpz_t *n)
{
  mpz_t t, e;
  struct is *stack = NULL;
  int k,i;

  if (ex == 0) {
    mpz_set_int(mrb,zz,1);
    return;
  }

  if (ex < 0) {
    return;
  }
  mpz_init_set_int(mrb,&e, ex);
  mpz_init(mrb,&t);

  for (k=0;!uzero(&e);k++,mpz_div_2exp(mrb,&e,&e,1))
    push(mrb,lowdigit(&e) & 1,&stack);
  k--;
  i=pop(mrb,&stack);

  mpz_mod(mrb,&t,x,n);  /* t=x%n */

  for (i=k-1;i>=0;i--) {
    mpz_mul(mrb,&t,&t,&t);
    mpz_mod(mrb,&t,&t,n);
    if (pop(mrb,&stack)) {
      mpz_mul(mrb,&t,&t,x);
      mpz_mod(mrb,&t,&t,n);
    }
  }
  mpz_set(mrb,zz,&t);
  mpz_clear(mrb,&t);
  mpz_clear(mrb,&e);
}

