  struct RBigint *bint = bint_new(mrb);
  mpz_t *r = &bint->mp;

  if (x < 0.0) {
    x = -x;
    r->sn = -1;
  }
  else {
    r->sn = 1;
  }

  mrb_float b = (double)CMASK;
  mrb_float bi = 1.0 / b;
  size_t rn, i;
  mp_limb *rp;
  mp_limb f;

  for (rn = 1; x >= b; rn++)
    x *= bi;

  mpz_realloc(mrb, r, rn);
  rp = r->p;
  for (i=rn-1;;i--) {
    f = (mp_limb)x;
    x -= f;
    mrb_assert(x < 1.0);
    rp[i] = f;
    if (i == 0) break;
  }
  return bint_norm(mrb, bint);
}

mrb_float
mrb_bint_as_float(mrb_state *mrb, mrb_value self)
{
  struct RBigint *b = RBIGINT(self);
  mpz_t *i = &b->mp;
  mp_limb *d = i->p + i->sz;
  mrb_float val = 0;

  while (d-- > i->p) {
    val = val * (LMAX+1) + *d;
  }

  if (i->sn < 0) {
    val = -val;
  }
  return val;
}
